/*
 * A039984  An example of a d-perfect sequence.
 * https://oeis.org/A039984
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) = A090345(n) mod 2
 * Range:     u8 n <= 105, u16 n <= 105, u32 n <= 105, u64 n <= 105,
 *            u128 n <= 105, big any n
 * Helpers:   next_letter
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* a(n) is the (n‑th) binary value from the morphic word generated by
   a → ab, b → cd, c → cd, d → bb, with the coding a,c,d → 1, b → 0. */

#include <stdint.h>   /* for standard integer types */
#include "../utils/next_letter.h"

/* Compute the n-th term of OEIS A039984 (1‑based). */
seq_t a(idx_t n)
{
    if (n == 0) return (seq_t)0;           /* out of range, harmless */

    idx_t k = n - 1;                       /* 0‑based index for binary traversal */

    char letter = 'a';                     /* start from the fixed point root */

    /* Determine position of the most significant bit of k. */
    int msb = -1;
    idx_t tmp = k;
    while (tmp != 0) {
        ++msb;
        tmp >>= 1;
    }
    if (msb >= 0) {
        /* Traverse bits from most significant to least significant. */
        for (int i = msb; i >= 0; --i) {
            int bit = (k >> i) & 1;        /* 0 or 1 */
            letter = next_letter(letter, bit + 1);   /* bit 0 → child 1, bit 1 → child 2 */
        }
    }

    /* Map the resulting letter to the binary output. */
    return (letter == 'b') ? (seq_t)0 : (seq_t)1;
}
